import{_ as t,a,c as s,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Redis 数据类型","description":"Redis 基础理论：String、Hash、List、Set、Sorted Set 的特点、选型与阅读入口，以及 Stream 等扩展学习方向。","frontmatter":{"title":"Redis 数据类型","description":"Redis 基础理论：String、Hash、List、Set、Sorted Set 的特点、选型与阅读入口，以及 Stream 等扩展学习方向。","showdocs":{"topics":[{"id":"redis","title":"Redis","link":"/topics/redis/"}],"kind":"数据与原子性","scope":"general","audience":"general","group":"数据库与存储","summary":"Redis 基础理论：String、Hash、List、Set、Sorted Set 的特点、选型与阅读入口，以及 Stream 等扩展学习方向。","status":"active","related":[{"title":"Redis 操作与命令","link":"/middleware/redis/plus/ecosystem/redis-general-general","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 数据类型命令速查","link":"/middleware/redis/plus/subjects/redis-data-cmd","kind":"数据与原子性","scope":"general","audience":"general"},{"title":"Redis 完整实践：Lua 原子限额与可重试 CLI","link":"/middleware/redis/plus/practice/quota","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 游戏与通用后端场景","link":"/middleware/redis/pro/practice/game-scenarios","kind":"完整实践","scope":"general","audience":"general"},{"title":"Redis 持久化：RDB、AOF 与独立恢复","link":"/middleware/redis/persistence-and-recovery","kind":"数据与原子性","scope":"general","audience":"general"}],"prev":false,"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":false},"headers":[],"relativePath":"middleware/redis/base/basic/data-types.md","filePath":"middleware/redis/base/basic/data-types.md"}'),d={name:"middleware/redis/base/basic/data-types.md"};function i(l,e,o,n,h,p){return a(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="redis-数据类型" tabindex="-1">Redis 数据类型 <a class="header-anchor" href="#redis-数据类型" aria-label="Permalink to &quot;Redis 数据类型&quot;">​</a></h1><p>学习 Redis 时，先根据数据的关系和访问方式选择类型，再学习对应命令。本页是数据类型的基础入口；动手前可阅读<a href="/middleware/redis/base/basic/start#environment">连接与首次运行</a>。</p><p>本页侧重类型对照和选型。plus 中每种类型都有独立文章：</p><ul><li><a href="/middleware/redis/plus/subjects/string">String（字符串）</a>：会话、计数、缓存与锁。</li><li><a href="/middleware/redis/plus/subjects/hash">Hash（哈希）</a>：对象字段、背包与保底计数。</li><li><a href="/middleware/redis/plus/subjects/list">List（列表）</a>：聊天历史、序列与队列。</li><li><a href="/middleware/redis/plus/subjects/set">Set（集合）</a>：好友、名单与兑换码。</li><li><a href="/middleware/redis/plus/subjects/sorted-set">Sorted Set（有序集合）</a>：排行榜、匹配与限流。</li><li><a href="/middleware/redis/plus/subjects/stream">Stream（消息流）</a>：事件消费与比赛结果入库。</li><li><a href="/middleware/redis/plus/subjects/bitmap">Bitmap（位图）</a>：日活、签到与留存。</li><li><a href="/middleware/redis/plus/subjects/hyperloglog">HyperLogLog（基数统计）</a>：活动参与人数。</li><li><a href="/middleware/redis/plus/subjects/geo">Geo（地理位置）</a>：附近玩家与经纬度查询。</li></ul><h2 id="overview" tabindex="-1">常用数据类型对照 <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;常用数据类型对照 {#overview}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>数据特点</th><th>典型用途</th><th>本页讲解</th></tr></thead><tbody><tr><td>String（字符串）</td><td>一个字节串</td><td>简单值、计数、序列化对象</td><td><a href="#string">String</a></td></tr><tr><td>Hash（哈希）</td><td>字段和值的集合</td><td>按字段访问对象</td><td><a href="#hash">Hash</a></td></tr><tr><td>List（列表）</td><td>有顺序、允许重复的元素序列</td><td>两端插入和弹出</td><td><a href="#list">List</a></td></tr><tr><td>Set（集合）</td><td>成员唯一、不保证顺序</td><td>去重、成员判断、集合运算</td><td><a href="#set">Set</a></td></tr><tr><td>Sorted Set / ZSet（有序集合）</td><td>成员唯一，按分数排序</td><td>排行榜、按分数查询</td><td><a href="#sorted-set">Sorted Set</a></td></tr></tbody></table><p>这五种是常用入门类型，并非 Redis 的全部能力。完整分类见 <a href="https://redis.io/docs/latest/develop/data-types/" target="_blank" rel="noopener noreferrer">Redis 官方数据类型文档</a>。</p><h2 id="string" tabindex="-1">String：整体读写一个值 <a class="header-anchor" href="#string" aria-label="Permalink to &quot;String：整体读写一个值 {#string}&quot;">​</a></h2><p>适合把一个值作为整体保存和读取。选择时先问：业务是每次读取整个对象，还是只修改其中一个字段？</p><p>阅读：<a href="/middleware/redis/plus/subjects/data#string">String 计数器示例</a> · <a href="/middleware/redis/plus/subjects/redis-strings">字符串命令速查</a>。</p><h2 id="hash" tabindex="-1">Hash：按字段访问对象 <a class="header-anchor" href="#hash" aria-label="Permalink to &quot;Hash：按字段访问对象 {#hash}&quot;">​</a></h2><p>适合用字段组织对象。与 String 保存整个对象相比，选型重点是是否需要分别访问字段。</p><p>阅读：<a href="/middleware/redis/plus/subjects/redis-hashes">Hash 命令速查</a> · <a href="/middleware/redis/plus/subjects/data#structures">数据结构操作示例</a>。</p><h2 id="list" tabindex="-1">List：维护元素顺序 <a class="header-anchor" href="#list" aria-label="Permalink to &quot;List：维护元素顺序 {#list}&quot;">​</a></h2><p>当重复元素和先后顺序都有意义时，可以从 List 开始理解。学习时重点观察从哪一端插入、从哪一端取出。</p><p>阅读：<a href="/middleware/redis/plus/subjects/redis-lists">List 命令速查</a> · <a href="/middleware/redis/plus/subjects/data#structures">队列示例及消费边界</a>。</p><h2 id="set" tabindex="-1">Set：表达成员关系 <a class="header-anchor" href="#set" aria-label="Permalink to &quot;Set：表达成员关系 {#set}&quot;">​</a></h2><p>适合回答“有哪些不同成员”“某个成员是否存在”。如果业务还要求固定顺序，需要进一步考虑排序需求。</p><p>阅读：<a href="/middleware/redis/plus/subjects/redis-sets">Set 命令速查</a>。</p><h2 id="sorted-set" tabindex="-1">Sorted Set：按分数排序 <a class="header-anchor" href="#sorted-set" aria-label="Permalink to &quot;Sorted Set：按分数排序 {#sorted-set}&quot;">​</a></h2><p>适合既要成员唯一、又要根据分数排序的关系。设计排行榜时，应先明确成员代表谁、分数代表什么、需要升序还是降序。</p><p>阅读：<a href="/middleware/redis/plus/subjects/redis-sorted-sets">Sorted Set 命令速查</a>。</p><h2 id="more-types" tabindex="-1">继续学习哪些类型 <a class="header-anchor" href="#more-types" aria-label="Permalink to &quot;继续学习哪些类型 {#more-types}&quot;">​</a></h2><p>在常用类型之后，可以按需求阅读官方的 <a href="https://redis.io/docs/latest/develop/data-types/streams/" target="_blank" rel="noopener noreferrer">Stream</a>、<a href="https://redis.io/docs/latest/develop/data-types/bitmaps/" target="_blank" rel="noopener noreferrer">Bitmap</a> 和 <a href="https://redis.io/docs/latest/develop/data-types/probabilistic/hyperloglogs/" target="_blank" rel="noopener noreferrer">HyperLogLog</a> 教程。使用其他类型前，核对目标 Redis 版本和部署提供的能力。</p><h2 id="next" tabindex="-1">下一步 <a class="header-anchor" href="#next" aria-label="Permalink to &quot;下一步 {#next}&quot;">​</a></h2><ul><li>想练习类型操作：阅读<a href="/middleware/redis/plus/subjects/data#string">数据结构与操作示例</a>。</li><li>想理解数据何时过期：阅读<a href="/middleware/redis/plus/subjects/data#ttl">TTL 与覆盖行为</a>。</li><li>想理解多条操作的保证：阅读<a href="/middleware/redis/plus/subjects/data#atomicity">Pipeline、事务与 Lua</a>。</li></ul>',26)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
